SELECT id, name, question_count, category, source, published, created_by FROM question_bank
WHERE created_by = #{userId}
AND (name LIKE CONCAT('%', #{query.keyword}, '%') OR category LIKE CONCAT('%', #{query.keyword}, '%'))
ORDER BY created_at DESC, id DESC LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT id, name, question_count, category, source, published
FROM question_bank
WHERE id = #{id}
